//! Compiler-observed implementation identity. This is build tooling, not
//! publication, compatibility, or currentness authority.
//!
//! The observer accepts workspace Rust inputs, exact observed extern artifacts,
//! lock-checksummed registry archives and locked Git trees. Extracted external
//! bytes must match their archive/tree. Its finite Cargo-generator contract
//! checks helpers and effects before executing the original compiled generator,
//! then checks actual directives and generated bytes. Serde Core 1.0.229 is a
//! qualified external/generated-input journey. Proc macros, native input
//! options, alternate sysroots, generator build dependencies and unsupported
//! generator effects refuse. These restrictions are qualification boundaries;
//! actual SDK/CAD closure support and Decl/Host producer adoption remain work.
//! A retained JSON description cannot construct a component in a later build.
//!
//! CLI: `implementation-edition build MANIFEST TARGET [cargo-build-args]`.
//! The target must be isolated. The CLI places observation before sccache,
//! keeps profile incremental defaults, and uses at most four Cargo jobs.
//!
//! The read-only component surface is usable without a digest constructor:
//! ```
//! use implementation_edition::{CompiledImplementation, ObservedCompilation};
//! fn describe(compilation: &ObservedCompilation) -> (&std::path::Path, &str, &str) {
//!     let component: &CompiledImplementation = compilation.implementation();
//!     (compilation.artifact(), component.closure_digest(), component.context_digest())
//! }
//! ```
//!
//! Ordinary callers cannot manufacture a component from a chosen digest:
//! ```compile_fail,E0451
//! use implementation_edition::CompiledImplementation;
//! let forged = CompiledImplementation { closure: "chosen".into(), context: "chosen".into() };
//! ```

mod cargo_build;
mod compiler_context;
mod fingerprint;
mod inputs;
mod observation;
mod package_content;
mod rust_identifier;
mod stamp;

use std::path::Path;

/// A verified compiler-input closure and its actual compiler-unit context.
/// There is no raw-digest constructor or deserializer. Serialized reports are
/// descriptions; the observer never accepts a report as construction authority.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CompiledImplementation {
    closure: String,
    context: String,
}

/// One artifact produced under the observer, including its concrete unit.
/// Artifact paths are local plumbing and are absent from component identity.
#[derive(Debug)]
pub struct ObservedCompilation {
    artifact: std::path::PathBuf,
    implementation: CompiledImplementation,
}

impl ObservedCompilation {
    pub fn artifact(&self) -> &Path {
        &self.artifact
    }
    pub fn implementation(&self) -> &CompiledImplementation {
        &self.implementation
    }
}

impl CompiledImplementation {
    /// Versioned, path-independent closure digest, including compiler context.
    pub fn closure_digest(&self) -> &str {
        &self.closure
    }

    /// Digest of actual compiler identity, target, flags, cfg and tracked env.
    pub fn context_digest(&self) -> &str {
        &self.context
    }
}

/// Run Cargo with compiler observation outside the configured sccache wrapper.
/// Only supported, verified compiler closures can produce components.
/// The supplied target directory must be dedicated to this observer.
pub fn build(
    manifest: &Path,
    target: &Path,
    cargo_args: &[String],
) -> Result<Vec<ObservedCompilation>, String> {
    cargo_build::build(manifest, target, cargo_args)
}

/// Dispatch Cargo's actual rustc-wrapper invocation. This always performs
/// compiler discovery and validation before invoking sccache/rustc.
#[doc(hidden)]
pub fn observe(compiler: &str, arguments: &[String]) -> Result<(), String> {
    observation::compile(compiler, arguments)
}

/// Cargo generator dispatcher. Its original compiled program remains the
/// executed generator; this entry observes its actual execution environment.
#[doc(hidden)]
pub fn observe_generator() -> Result<(), String> {
    observation::generator_execution::run()
}
